def dossier_authorizes_effects(self, dossier_id: int) -> bool:
    """Return whether a dossier crossed either lawful promulgation path."""
    row = self.conn.execute(
        """
        SELECT d.status,d.promulgation_decision,
               EXISTS(
                   SELECT 1 FROM decree_dossier_decisions h
                   WHERE h.dossier_id=d.id
                     AND h.rescript_action='force_promulgated'
               ) AS was_force_promulgated
        FROM decree_dossiers d WHERE d.id=?
        """,
        (int(dossier_id),),
    ).fetchone()
    if row is None:
        return False
    return (
        str(row["status"] or "") in {"promulgated", "executing"}
        or str(row["promulgation_decision"] or "") == "promulgated"
        or bool(row["was_force_promulgated"])
    )

def _category_for_audience_night_error(exc: AudienceNightError) -> str:
    """按 `exc.code` 还原真因，不把召对夜域各种失败统一冒称 hallucinated_id。"""
    if exc.code in _NIGHT_CONTEXT_ERROR_CODES:
        return "missing_ref"  # 引用了不存在 / 已收/ 收夜中的夜——夜本身是缺失的引用
    if exc.code == "dead_present":
        return "invalid_state"  # 人物真实存在，只是状态（已殁）不容许这个动作
    return "invalid_enum"  # bad_audibility / bad_presence_effect 等既有枚举校验

def _spawn_legacy_from_effect(
    db: GameDB,
    state: GameState,
    effect: Dict[str, object],
    issue_id: int,
    issue_title: str,
    commit: bool = True,
) -> Optional[Dict[str, object]]:
    """结案 effect 里若带 legacy（帝国修正）段，落 legacies 表。返回落地摘要供日志。
    legacy schema:
      {"name": str,
       "duration": "1年"|"2年"|"永久",
       "modifiers": {                         # 各维度带符号百分比修正符
         "国库": +10, "内库": -5,                    # 账户增量
         "regions": {"shaanxi": {"unrest": -20}},   # 地区分数字段（仅 REGION_SCORE_FIELDS）
         "armies":  {"jizhou": {"morale": 15}}      # 军队分数字段（仅 ARMY_SCORE_FIELDS）
       },
       "narrative_hint": str}
    各 pct 带符号整数；落账时同维度累加，base>=0 ×(1+net/100)、base<0 ×(1-net/100)。
    缺字段/非法档/空 effect 一律跳过（不抛断）；地区/军队非法字段或不存在 id 由落账层忽略。
    """
    legacy = effect.get("legacy")
    if not isinstance(legacy, dict):
        return None
    name = str(legacy.get("name") or "") or f"{issue_title}遗留"
    dur_key = str(legacy.get("duration") or "2年").strip()
    duration = _LEGACY_DURATION_MONTHS.get(dur_key)
    if duration is None:
        print(f"[WARN] legacy 时长档非法 '{dur_key}'，按 2年 处理。")
        duration = 24
    raw_eff = legacy.get("modifiers") or {}
    modifiers: Dict[str, object] = {}
    if isinstance(raw_eff, dict):
        for k in _LEGACY_ACCOUNT_KEYS:
            pct = _clamp_pct(raw_eff.get(k))
            if pct is not None:
                modifiers[k] = pct
        for scope, allowed, aliases in (
            ("regions", REGION_SCORE_FIELDS + FISCAL_SCORE_FIELDS, REGION_FIELD_ALIASES),
            ("armies", ARMY_SCORE_FIELDS, ARMY_FIELD_ALIASES),
        ):
            block = raw_eff.get(scope)
            if not isinstance(block, dict):
                continue
            scope_out: Dict[str, Dict[str, int]] = {}
            for entity_id, fields in block.items():
                if not isinstance(fields, dict):
                    continue
                fields_out: Dict[str, int] = {}
                for raw_field, v in fields.items():
                    field = aliases.get(str(raw_field).strip(), str(raw_field).strip())
                    if field not in allowed:
                        print(f"[INFO] legacy '{name}' {scope} 字段 '{raw_field}' 非法/不可修正，跳过。")
                        continue
                    pct = _clamp_pct(v)
                    if pct is not None:
                        fields_out[field] = pct
                if fields_out:
                    scope_out[str(entity_id)] = fields_out
            if scope_out:
                modifiers[scope] = scope_out
    if not modifiers:
        print(f"[INFO] legacy '{name}' 无有效 modifiers，跳过。")
        return None
    new_id = db.insert_legacy(
        state,
        name=name,
        modifiers=modifiers,
        narrative_hint=str(legacy.get("narrative_hint") or ""),
        duration_months=duration,
        source_issue_id=issue_id,
        commit=commit,
    )
    summary = {
        "legacy_id": new_id, "name": name,
        "duration_months": duration, "modifiers": modifiers,
    }
    dur_label = "永久" if duration < 0 else f"{duration}月"
    print(f"[帝国修正] 局势#{issue_id}「{issue_title}」落「{name}」({dur_label}) {modifiers}")
    return summary

def _run_output_status_is_error(run_output: object) -> bool:
    """agno Agent.run 失败时 status=RunStatus.error（值 'ERROR'），content=str(exc)。

    #1299/#1310：此 status 是 runner/provider 失败的权威信号；不得把 content 当叙事放行。
    """
    status = getattr(run_output, "status", None)
    if status is None:
        return False
    raw = getattr(status, "value", status)
    return str(raw).strip().upper() in {"ERROR", "FAILED"}

