def append_decree_dossier_participants(
    self, dossier_id: int, participants: Iterable[object], *,
    state: Optional[GameState] = None, commit: bool = True,
) -> List[Dict[str, object]]:
    """Append ADR 0053 roster entries without replacing durable members."""
    row = self.conn.execute(
        "SELECT participant_roster,action_type,decree_text FROM decree_dossiers WHERE id=?",
        (int(dossier_id),),
    ).fetchone()
    if row is None:
        raise KeyError(f"案卷不存在：{dossier_id}")
    try:
        existing_raw = json.loads(row["participant_roster"] or "[]")
    except (TypeError, ValueError):
        existing_raw = []
    existing = self._normalize_participant_roster(
        existing_raw if isinstance(existing_raw, list) else []
    )
    additions = self._normalize_participant_roster(participants, strict_structured=True)
    self._validate_participant_roster_references(additions)
    by_character = {str(item["character_id"]): item for item in existing}
    added: List[Dict[str, object]] = []
    for item in additions:
        character_id = str(item["character_id"])
        prior = by_character.get(character_id)
        if prior is not None:
            if prior != item:
                raise ValueError(f"参与人物已在案且机械档不同：{character_id}")
            continue
        by_character[character_id] = item
        added.append(item)
    merged = existing + added
    self._validate_dossier_delegations(merged)
    self._validate_participant_roster_references(merged)
    if added:
        archive_keys: set[str] = set()
        raw_keys_row = self.conn.execute(
            "SELECT office_archive_keys FROM decree_dossiers WHERE id=?",
            (int(dossier_id),),
        ).fetchone()
        raw_keys = (
            raw_keys_row["office_archive_keys"] if raw_keys_row is not None else None
        ) or "[]"
        parsed_keys = json.loads(raw_keys)
        if not isinstance(parsed_keys, list):
            raise ValueError(
                f"office_archive_keys 须为 JSON 数组：dossier {int(dossier_id)}"
            )
        archive_keys = {str(item) for item in parsed_keys}
        if str(row["action_type"] or "") != "secret_order":
            for item in added:
                if str(item.get("tier") or "") != "主办":
                    continue
                lead_name = str(item.get("character_id") or "")
                lead = self.conn.execute(
                    "SELECT office,office_type,location FROM characters WHERE name=?",
                    (lead_name,),
                ).fetchone()
                if lead is None:
                    continue
                key = self._office_archive_key(
                    lead["office"], lead["office_type"],
                    location=lead["location"] if "location" in lead.keys() else "",
                    character_name=lead_name,
                )
                if key:
                    archive_keys.add(key)
        self.conn.execute(
            "UPDATE decree_dossiers SET participant_roster=?,office_archive_keys=?,"
            "updated_at=CURRENT_TIMESTAMP WHERE id=?",
            (
                json.dumps(merged, ensure_ascii=False),
                json.dumps(sorted(archive_keys), ensure_ascii=False),
                int(dossier_id),
            ),
        )
        if state is not None and str(row["action_type"] or "") != "secret_order":
            for item in added:
                identity = ":".join(str(item.get(key) or "-") for key in (
                    "character_id", "tier", "role", "delegator_id",
                ))

def _attach_commission_staging_fields(
    payload: Dict[str, Any], item: Mapping[str, object], *, turn: int,
) -> None:
    """透传既有 staging 字段：assignee / participant_roster / due_turn。

    字段可在交办顶层，或挂在 grant 对象内（与 stage_grant_allocation_candidate
    kwargs 同口径）。期限单源＝due_turn；deadline_months / end_turn 仅作换算输入。
    """
    grant = item.get("grant") if isinstance(item.get("grant"), Mapping) else {}
    lead = str(
        item.get("assignee")
        or item.get("assignee_id")
        or item.get("assignee_name")
        or (grant.get("assignee") if grant else "")
        or (grant.get("assignee_id") if grant else "")
        or ""
    ).strip()
    if lead:
        payload["assignee"] = lead
    roster = item.get("participant_roster")
    if not isinstance(roster, list) and grant:
        roster = grant.get("participant_roster")
    if isinstance(roster, list) and roster:
        payload["participant_roster"] = list(roster)
    elif lead and not isinstance(payload.get("participant_roster"), list):
        payload["participant_roster"] = [{
            "character_id": lead, "tier": "主办", "role": "", "delegator_id": None,
        }]
    due_src = item if item.get("due_turn") not in (None, "", 0) else grant
    end_src = item if item.get("end_turn") not in (None, "", 0) else grant
    months_src = (
        item if item.get("deadline_months") not in (None, "", 0) else grant
    )
    # 与 stage_assignment / stage_grant 同缝：相对月数或绝对回合 → 绝对 due_turn。
    absolute_due = _assignment_absolute_end_turn(
        int(turn),
        end_turn=(due_src or item).get("due_turn") or (end_src or item).get("end_turn") or 0,
        deadline_months=(months_src or item).get("deadline_months") or 0,
    )
    if absolute_due > int(turn):
        payload["due_turn"] = absolute_due

def experiences(self, affair_id: int) -> tuple[dict[str, object], ...]:
    """Read-time projection: story-ledger rows whose origin_ref points at this affair."""
    self.get(affair_id)
    refs = self.origin_refs(affair_id)
    affair_ref = self.origin_ref(affair_id)
    placeholders = ",".join("?" for _ in refs)
    rows = self._conn.execute(
        "SELECT id, person_names, tags, body, origin_ref "
        "FROM story_ledger_entries WHERE origin_ref IN ("
        + placeholders
        + ") OR origin_ref LIKE ? ORDER BY id",
        (*refs, f"{affair_ref}/%"),
    ).fetchall()
    out: list[dict[str, object]] = []
    for row in rows:
        origin = str(row["origin_ref"] or "").strip()
        try:
            tags = json.loads(row["tags"] or "[]")
        except (TypeError, ValueError):
            tags = []
        if not isinstance(tags, list):
            tags = []
        try:
            people = json.loads(row["person_names"] or "[]")
        except (TypeError, ValueError):
            people = []
        if not isinstance(people, list):
            people = []
        out.append({
            "id": int(row["id"]),
